*
* Static destination metadata only: ids, zones, Home Point numbers, city
* groups, unlock bits, key items, expansion. The data is generated by
* tools/gen_catalog.lua from LandSandBoat/Phoenix sources into
* catalog_data.lua (1.1.0; see docs/CATALOGUE.md).
* Character state (unlocks, balances) stays in model.lua; withUnlocks() and
* filter() combine the two without copying model data into the catalog.
*
* Display names come from the player's client at runtime
* (IResourceManager:GetString, 'zones.names' / 'keyitems.names', as used by
* the stock Ashita addons blucheck, renamer and itemwatch). A successful
* lookup is cached for good; a failed or empty one is NOT cached as a name:
* a fallback is shown and the lookup is retried after RETRY_MS, so a
* temporary failure heals without per-frame lookups.
*
* Rows returned by rows()/get() are shared tables: treat them as read-only.
--]]

local K = {}

K.RETRY_MS = 5000
K.TABS     = { 'hp', 'sg', 'sp', 'rp' }
K.EXPECTED = { hp = 104, sg = 77, sp = 6, rp = 6 }
K.EXPANSION_LABELS = {
    base = 'Original',
    roz  = 'Rise of the Zilart',
    cop  = 'Chains of Promathia',
    toau = 'Treasures of Aht Urhgan',
}

local S = {
    data     = nil,
    loaded   = false,
    err      = nil,
    rows     = {},
    byId     = {},
    names    = { ['zones.names'] = {}, ['keyitems.names'] = {} },
    revision = 0, -- bumps whenever a client name resolves (search keys rebuild)
}

-----------------------------------------------------------------------------
-- Helpers
-----------------------------------------------------------------------------

local function nowMs()
    local ok, c = pcall(ashita.time.clock)

    if ok and type(c) == 'table' and type(c.ms) == 'number' then
        return c.ms
    end

    return os.time() * 1000
end

-- Client string -> usable text, or nil when empty/unusable. Cuts at NUL,
-- drops control characters, trims. Bytes >= 0x80 are kept as returned.
local function clean(s)
    if type(s) ~= 'string' then
        return nil
    end

    local nul = string.find(s, '\0', 1, true)

    if nul ~= nil then
        s = string.sub(s, 1, nul - 1)
    end

    s = string.gsub(s, '%c', '')
    s = string.gsub(s, '^%s+', '')
    s = string.gsub(s, '%s+$', '')

    if s == '' then
        return nil
    end

    return s
end

-- 'SOUTHERN_SAN_DORIA' -> 'Southern San Doria' (fallback display only).
local function enumTitle(enum)
    if type(enum) ~= 'string' or enum == '' then
        return nil
    end

    local words = {}

    for w in string.gmatch(string.lower(enum), '[^_]+') do
        words[#words + 1] = string.upper(string.sub(w, 1, 1)) .. string.sub(w, 2)
    end

    return table.concat(words, ' ')
end

-- Search normalisation for BOTH indexed text and queries (features B1):
-- lower case, every character that is not an ASCII letter or digit removed.
-- "San d'Oria" -> "sandoria", "#1" -> "1".
function K.normalize(s)
    if type(s) ~= 'string' then
        return ''
    end

    return (string.gsub(string.lower(s), '[^%w]', ''))
end

-----------------------------------------------------------------------------
-- Client names with retry
-----------------------------------------------------------------------------

-- Returns text or nil. Successful text is cached; failures are retried after
-- RETRY_MS (never more often).
local function lookup(tbl, id)
    local cache = S.names[tbl]
    local e     = cache[id]

    if e ~= nil and e.ok then
        return e.text
    end

    local t = nowMs()

    if e ~= nil and (t - e.at) < K.RETRY_MS then
        return nil
    end

    local ok, s = pcall(function ()
        return AshitaCore:GetResourceManager():GetString(tbl, id)
    end)
    local text  = ok and clean(s) or nil
    local tries = (e and e.tries or 0) + 1

    if text ~= nil then
        cache[id] = { ok = true, text = text, at = t, tries = tries }
        S.revision = S.revision + 1
        return text
    end

    cache[id] = { ok = false, at = t, tries = tries, why = ok and 'empty or missing string' or tostring(s) }
    return nil
end

-- Zone display name and whether it came from the client.
function K.zoneName(zone)
    local text = lookup('zones.names', zone)

    if text ~= nil then
        return text, true
    end

    local z = S.data and S.data.zones[zone]
    return enumTitle(z and z.enum) or ('Zone ' .. tostring(zone)), false
end

function K.keyItemName(id)
    local text = lookup('keyitems.names', id)

    if text ~= nil then
        return text, true
    end

    return 'Key item ' .. tostring(id), false
end

-----------------------------------------------------------------------------
-- Loading
-----------------------------------------------------------------------------

function K.load()
    local ok, data = pcall(require, 'ffxiport.catalog_data')

    if not ok or type(data) ~= 'table' or type(data.zones) ~= 'table' then
        S.loaded = false
        S.err    = 'catalog_data.lua could not be loaded: ' .. tostring(data)
        return false, S.err
    end

    S.data = data
    S.rows = {}
    S.byId = {}

    for _, tab in ipairs(K.TABS) do
        local list, index = {}, {}

        for _, raw in ipairs(data[tab] or {}) do
            local z   = data.zones[raw.zone]
            local row = {
                tab     = tab,
                id      = raw.id,
                zone    = raw.zone,
                exp     = z and z.exp or nil,
                num     = raw.num,
                group   = raw.group,
                sgGroup = raw.sgGroup,
                sgIndex = raw.sgIndex,
                keyItem = raw.keyItem,
                crystal = raw.crystal,
                label   = raw.label,
            }

            list[#list + 1] = row
            index[row.id]   = row
        end

        S.rows[tab] = list
        S.byId[tab] = index
    end

    S.loaded = true
    S.err    = nil
    return true
end

function K.loaded()  return S.loaded, S.err end
function K.version() return S.data and S.data.version or nil end
function K.tabs()    return K.TABS end

function K.rows(tab)
    return S.rows[tab] or {}
end

function K.get(tab, id)
    local index = S.byId[tab]
    return index and index[id] or nil
end

function K.counts()
    local c = {}

    for _, tab in ipairs(K.TABS) do
        c[tab] = #(S.rows[tab] or {})
    end

    return c
end

-- Home Point city group of a zone (1..9), or nil when not a city.
function K.cityOf(zone)
    return S.data and S.data.city[zone] or nil
end

function K.expansionOf(row)
    return row and row.exp or nil
end

function K.expansionLabel(exp)
    return K.EXPANSION_LABELS[exp] or '?'
end

-----------------------------------------------------------------------------
-- Display text
-----------------------------------------------------------------------------

-- Main display name of a row:
--   hp "<zone> #<n>"   sg "<zone>"   sp "<crystal>" (Holla ...)   rp "<staging point>"
function K.name(row)
    if row == nil then
        return '?'
    end

    if row.tab == 'hp' then
        return K.zoneName(row.zone) .. ' #' .. tostring(row.num)
    elseif row.tab == 'sg' then
        return (K.zoneName(row.zone))
    elseif row.tab == 'sp' then
        return row.crystal or '?'
    elseif row.tab == 'rp' then
        return row.label or '?'
    end

    return '?'
end

-- Destination zone name (supplementary text for sp/rp rows).
function K.destination(row)
    return row and (K.zoneName(row.zone)) or '?'
end

-- What the server requires besides the unlock bit itself: for Gate Crystals
-- the key item only (never a spell, job or MP); nil for other tabs.
function K.requirement(row)
    if row ~= nil and row.tab == 'sp' and row.keyItem ~= nil then
        return (K.keyItemName(row.keyItem))
    end

    return nil
end

-- Normalised search key: name, zone (client and enum spelling), Home Point
-- number, crystal and key item names, staging point label. Rebuilt only
-- when a client name has resolved since the key was built.
function K.searchKey(row)
    if row._keyRev == S.revision and row._key ~= nil then
        return row._key
    end

    local z     = S.data and S.data.zones[row.zone]
    local parts = { K.name(row), K.destination(row), enumTitle(z and z.enum) or '' }

    if row.tab == 'sp' then
        parts[#parts + 1] = row.crystal or ''
        parts[#parts + 1] = K.requirement(row) or ''
    elseif row.tab == 'rp' then
        parts[#parts + 1] = row.label or ''
    end

    row._key    = K.normalize(table.concat(parts, ' '))
    row._keyRev = S.revision
    return row._key
end

-- True when the normalised query is empty or contained in the row's key.
function K.matches(row, query)
    local q = K.normalize(query)

    if q == '' then
        return true
    end

    return string.find(K.searchKey(row), q, 1, true) ~= nil
end

-----------------------------------------------------------------------------
-- Combining with model.lua (no model data is stored here)
-----------------------------------------------------------------------------

-- true / false / nil (no model or no validated sync). Written without the
-- `a and b or nil` idiom, which would turn a locked row (false) into nil.
local function unlockOf(model, tab, row)
    if model == nil then
        return nil
    end

    return model.isUnlocked(tab, row)
end

-- { { row = row, unlocked = true|false|nil }, ... }; nil = no validated sync.
function K.withUnlocks(tab, model)
    local out = {}

    for _, row in ipairs(K.rows(tab)) do
        out[#out + 1] = { row = row, unlocked = unlockOf(model, tab, row) }
    end

    return out
end

-- opts: { text = query, onlyUsable = bool, model = model }
function K.filter(tab, opts)
    opts = opts or {}

    local out = {}
    local q   = opts.text or ''

    for _, row in ipairs(K.rows(tab)) do
        if K.matches(row, q) then
            local unlocked = unlockOf(opts.model, tab, row)

            if not opts.onlyUsable or unlocked == true then
                out[#out + 1] = { row = row, unlocked = unlocked }
            end
        end
    end

    return out
end

-----------------------------------------------------------------------------
-- Diagnostics
-----------------------------------------------------------------------------

-- Runtime self-check of the loaded data. Returns ok, problems.
function K.verify()
    local problems = {}

    local function add(text)
        problems[#problems + 1] = text
    end

    if not S.loaded then
        add(S.err or 'not loaded')
        return false, problems
    end

    if S.data.version ~= 7 then
        add('catalog version ' .. tostring(S.data.version) .. ', expected 7')
    end

    local sgBits = {}

    for _, tab in ipairs(K.TABS) do
        local rows = S.rows[tab]

        if #rows ~= K.EXPECTED[tab] then
            add(tab .. ': ' .. #rows .. ' rows, expected ' .. K.EXPECTED[tab])
        end

        local seen = {}

        for _, row in ipairs(rows) do
            if seen[row.id] then
                add(tab .. ': duplicate id ' .. tostring(row.id))
            end

            seen[row.id] = true

            if K.EXPANSION_LABELS[row.exp] == nil then
                add(tab .. ' ' .. tostring(row.id) .. ': no expansion for zone ' .. tostring(row.zone))
            end

            if tab == 'hp' and (type(row.num) ~= 'number' or row.num < 1 or type(row.group) ~= 'number') then
                add('hp ' .. tostring(row.id) .. ': bad number/group')
            elseif tab == 'hp' and row.group ~= 0 and K.cityOf(row.zone) ~= row.group then
                add('hp ' .. tostring(row.id) .. ': city map disagrees with group')
            elseif tab == 'sg' then
                local g, i = row.sgGroup, row.sgIndex

                if type(g) ~= 'number' or type(i) ~= 'number' or g < 1 or g > 4 or i < 1 or i > 32 then
                    add('sg ' .. tostring(row.id) .. ': bad unlock bit')
                else
                    local key = g .. ':' .. i

                    if sgBits[key] then
                        add('sg ' .. tostring(row.id) .. ': unlock bit ' .. key .. ' shared')
                    end

                    sgBits[key] = true
                end
            elseif tab == 'sp' and (type(row.keyItem) ~= 'number' or type(row.crystal) ~= 'string') then
                add('sp ' .. tostring(row.id) .. ': missing key item or crystal name')
            elseif tab == 'rp' and (row.id < 1 or row.id > 6 or type(row.label) ~= 'string') then
                add('rp ' .. tostring(row.id) .. ': bad portal id or label')
            end
        end
    end

    return #problems == 0, problems
end

-- Looks up every catalog zone and key item name (respecting RETRY_MS) and
-- reports which came from the client and which use a fallback.
function K.nameStats()
    local st = { zones = 0, zonesResolved = 0, keyItems = 0, keyItemsResolved = 0, nonAscii = 0, unresolved = {} }

    if not S.loaded then
        return st
    end

    local function note(tbl, id, label, fallback)
        local e = S.names[tbl][id]

        st.unresolved[#st.unresolved + 1] = string.format('%s %d -> fallback "%s" (%s, %d tries)',
            label, id, fallback, e and e.why or 'not tried', e and e.tries or 0)
    end

    local zones = {}

    for z in pairs(S.data.zones) do
        zones[#zones + 1] = z
    end

    table.sort(zones)

    for _, z in ipairs(zones) do
        st.zones = st.zones + 1

        local text, fromClient = K.zoneName(z)

        if fromClient then
            st.zonesResolved = st.zonesResolved + 1

            if string.find(text, '[\128-\255]') then
                st.nonAscii = st.nonAscii + 1
            end
        else
            note('zones.names', z, 'zone', text)
        end
    end

    for _, row in ipairs(S.rows.sp or {}) do
        st.keyItems = st.keyItems + 1

        local text, fromClient = K.keyItemName(row.keyItem)

        if fromClient then
            st.keyItemsResolved = st.keyItemsResolved + 1

            if string.find(text, '[\128-\255]') then
                st.nonAscii = st.nonAscii + 1
            end
        else
            note('keyitems.names', row.keyItem, 'key item', text)
        end
    end

    return st
end

return K
